import json

policy = json.loads("""{
  "Version": "2012-10-17",
  "Statement": [
    {"Effect": "Allow", "Action": "s3:GetObject", "Resource": "arn:aws:s3:::orders-export/*"},
    {"Effect": "Allow", "Action": "kms:*", "Resource": "*"},
    {"Effect": "Allow", "Action": ["secretsmanager:GetSecretValue"], "Resource": "*",
     "Condition": {"StringEquals": {"aws:ResourceTag/team": "order"}}}
  ]
}""")


def as_list(v):
    return v if isinstance(v, list) else [v]


for i, st in enumerate(policy["Statement"]):
    if st["Effect"] != "Allow":
        continue
    acts, res = as_list(st["Action"]), as_list(st["Resource"])
    wild_act = [a for a in acts if a == "*" or a.endswith(":*")]
    wild_res = "*" in res
    if wild_act and wild_res:
        print(f"#{i} 위험: {wild_act} 를 모든 리소스에 — 범위를 좁혀야 함")
    elif wild_res and "Condition" not in st:
        print(f"#{i} 주의: Resource '*' 인데 조건 없음")
    elif wild_res:
        print(f"#{i} 통과(조건부): Resource '*' 지만 Condition {list(st['Condition'])} 로 좁힘")
    else:
        print(f"#{i} 통과: {acts} → {res}")
